from pathlib import Path
p=Path('scripts/recover_official_best_partner_images.py')
s=p.read_text()
s=s.replace('''    # Prefer the first JAN-named image embedded in the official product page.\n    # Try its largest srcset original first, then the remaining images in page order.\n    output: list[str] = []\n    for group in groups:\n        for _, url in group:\n            if url not in output:\n                output.append(url)\n''','''    # Prefer original uploads over WordPress resized variants. Preserve page order:\n    # the supplier uses JAN.jpg for the package and JAN-1.jpg for the contents.\n    output: list[str] = []\n    for group in groups:\n        originals = [url for _, url in group if not re.search(r"-\\d+x\\d+\\.(?:jpe?g|png|webp)$", urlparse(url).path, re.I)]\n        candidates = originals or [url for _, url in group]\n        for url in candidates:\n            if url not in output:\n                output.append(url)\n''')
start=s.index('def recover_one(jan: str) -> dict:')
end=s.index('def read_inputs(', start)
new='''def recover_one(jan: str) -> dict:\n    result = {\n        "jan": jan, "status": "unresolved", "detail": "",\n        "product_page_url": "", "source_image_urls": [], "source_images": [],\n        "webp_paths": [f"/images/products/{jan}-1.webp", f"/images/products/{jan}-2.webp"],\n        "payloads": [],\n    }\n    try:\n        page_url, detail = search_product_page(jan)\n        result["detail"] = detail\n        if not page_url:\n            return result\n        result["product_page_url"] = page_url\n        page = request_get(page_url)\n        if page.status_code != 200:\n            result["detail"] = f"product_page_http_{page.status_code}"\n            return result\n        normalized = normalize_text(BeautifulSoup(page.content, "html.parser").get_text(" ", strip=True))\n        if jan not in normalized:\n            result["detail"] = "exact_jan_missing_after_fetch"\n            return result\n        candidates = official_image_candidates(page.url, jan, page.content)\n        if not candidates:\n            result["detail"] = "no_official_image_url_named_with_jan"\n            return result\n        payloads = []\n        source_urls = []\n        source_meta = []\n        errors = []\n        for image_url in candidates:\n            try:\n                response = request_get(image_url, referer=page.url)\n                if response.status_code != 200 or len(response.content) > 15 * 1024 * 1024:\n                    errors.append(f"http_or_size:{response.status_code}")\n                    continue\n                if not response.headers.get("Content-Type", "").lower().startswith("image/"):\n                    continue\n                with Image.open(BytesIO(response.content)) as source:\n                    source.verify()\n                with Image.open(BytesIO(response.content)) as source:\n                    dimensions = source.size\n                    if min(dimensions) < 250:\n                        continue\n                    webp, quality, out_dimensions = encode_webp(source)\n                payloads.append(webp)\n                source_urls.append(response.url)\n                source_meta.append({"source_dimensions": f"{dimensions[0]}x{dimensions[1]}", "source_bytes": len(response.content), "webp_dimensions": f"{out_dimensions[0]}x{out_dimensions[1]}", "webp_bytes": len(webp), "webp_quality": quality, "sha256": hashlib.sha256(webp).hexdigest()})\n            except (requests.RequestException, UnidentifiedImageError, OSError, ValueError) as exc:\n                errors.append(type(exc).__name__)\n        if not payloads:\n            result["detail"] = errors[-1] if errors else "no_valid_image_candidates"\n            return result\n        result.update({"status": "recovered", "detail": "official_product_page_exact_jan_and_jan_named_images", "source_image_urls": source_urls, "source_images": source_meta, "payloads": payloads})\n        if len(payloads) < 2:\n            result["detail"] += "_only_one_official_image"\n        return result\n    except requests.RequestException as exc:\n        result["detail"] = f"request_error:{type(exc).__name__}"\n        return result\n    except Exception as exc:\n        result["detail"] = f"processing_error:{type(exc).__name__}:{exc}"\n        return result\n\n'''
s=s[:start]+new+s[end:]
start=s.index('def write_results(')
end=s.index('def main()', start)
new='''def write_results(\n    args: argparse.Namespace, missing_rows: list[dict], catalog: dict, results: list[dict],\n) -> tuple[int, int]:\n    by_jan = {result["jan"]: result for result in results}\n    recovered = {jan: result for jan, result in by_jan.items() if result["status"] == "recovered"}\n    written_images = 0\n    for jan, result in recovered.items():\n        for index, payload in enumerate(result.pop("payloads"), start=1):\n            destination = args.output_dir / f"{jan}-{index}.webp"\n            temp = destination.with_suffix(destination.suffix + ".tmp")\n            temp.write_bytes(payload)\n            temp.replace(destination)\n            written_images += 1\n        result["webp_paths"] = [f"/images/products/{jan}-{i}.webp" for i in range(1, len(result["source_image_urls"]) + 1)]\n    updated_products = 0\n    for product in catalog["products"]:\n        jan = extract_jan(str(product.get("mofu_sku") or product.get("sku") or ""))\n        if jan not in recovered:\n            continue\n        paths = recovered[jan]["webp_paths"]\n        product["image_url"] = paths[0]\n        product["images"] = paths\n        updated_products += 1\n    temp_catalog = args.catalog.with_suffix(args.catalog.suffix + ".tmp")\n    temp_catalog.write_text(json.dumps(catalog, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n    temp_catalog.replace(args.catalog)\n    args.report.parent.mkdir(parents=True, exist_ok=True)\n    fieldnames = ["product_id", "mofu_sku", "name_zh", "name_en", "pet_species", "jan", "status", "detail", "product_page_url", "source_image_urls", "webp_paths", "source_images"]\n    with args.report.open("w", encoding="utf-8-sig", newline="") as file:\n        writer = csv.DictWriter(file, fieldnames=fieldnames, extrasaction="ignore")\n        writer.writeheader()\n        for row in missing_rows:\n            result = by_jan.get(row.get("_jan", ""), {})\n            writer.writerow({**row, **result, "jan": row.get("_jan", ""), "source_image_urls": json.dumps(result.get("source_image_urls", []), ensure_ascii=False), "webp_paths": json.dumps(result.get("webp_paths", []), ensure_ascii=False), "source_images": json.dumps(result.get("source_images", []), ensure_ascii=False)})\n    manifest_results = [{key: value for key, value in result.items() if key not in {"payload", "payloads"}} for result in results]\n    manifest = {"generated_at": datetime.now(timezone.utc).isoformat(), "source": "https://best-partner.co.jp/", "input_csv": str(args.missing_csv), "catalog": str(args.catalog), "summary": {"unique_jans_processed": len(results), "unique_jans_recovered": len(recovered), "unique_jans_with_two_images": sum(len(r.get("source_image_urls", [])) >= 2 for r in recovered.values()), "product_rows_updated": updated_products, "images_written": written_images}, "results": manifest_results}\n    args.manifest.parent.mkdir(parents=True, exist_ok=True)\n    args.manifest.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n    return updated_products, written_images\n'''
s=s[:start]+new+s[end:]
s=s.replace('''            result.pop("payload", None)\n            print(json.dumps(result, ensure_ascii=False))''','''            result.pop("payloads", None)\n            print(json.dumps(result, ensure_ascii=False))''')
p.write_text(s)
